/// <summary>
///  Class to help import data SNAllianceClients from ax2009
/// </summary>
internal final class NDXSNAllianceClientsProcess extends NDXTransferToD365 implements NDXTransferToD365Interface
{
    NDXSNAllianceClients lNDXSNAllianceClients;
    Niedax.AX.TableRecordModels.NDXSNAllianceClients ndxSNAllianceClientsModel;

}

Method.Source:
/// <summary>
/// writes markupAutoTable to database
/// </summary>
/// <param name = "_record">markupAutoTable object</param>
private void writeNDXSNAllianceClients(Niedax.AX.TableRecordModels.TableRecord _record)
{
    System.Exception ex;

    NDXCompany ndxCompany;
    NDXCompanyBE ndxCompanyBE;
    str message = '';
    ndxSNAllianceClientsModel = _record;

    response.Message = strFmt("@NDX:NDXSNAPITransferInfo3", ndxSNAllianceClientsModel.D365TableName
                    , ndxSNAllianceClientsModel.ToString()
                    , this.environment);

    if(_record.IsAX2009)
    {
        ndxCompany = ndxSNAllianceClientsModel.Companys;
        ndxCompanyBE = NDXHelperCommon::CompanyId2NDXCompanyBE(ndxCompany);
        ndxSNAllianceClientsModel.Companys = ndxCompanyBE;
    }

    lNDXSNAllianceClients = NDXSNAllianceClients::findTosIdChild(ndxSNAllianceClientsModel.Child, ndxSNAllianceClientsModel.Companys, ndxSNAllianceClientsModel.TOSId, true);

    try
    {
        //Make only updates on an existing record, since the records are created by determination process in d365
        if(!lNDXSNAllianceClients)
        {
            message = strFmt("@NDX:NDXSNAPITransferInfo1",  this.environment, ndxSNAllianceClientsModel.ToString());
            throw Error(message);
        }
        else
        {
            ttsbegin;
            lNDXSNAllianceClients.ChildMap = ndxSNAllianceClientsModel.ChildMap;
            lNDXSNAllianceClients.Active = ndxSNAllianceClientsModel.Active;
            lNDXSNAllianceClients.write();
            ttscommit;
            response.Success = true;
            response.RecId = lNDXSNAllianceClients.RecId;
        }

    }
    catch(ex)
    {
        message = message + "-" + ex.Message;
        response.RecId = 0;
    }

    response.Message = message;
}

/// <summary>
/// Updates or creates corresponding record
/// </summary>
/// <param name = "_record">record instance</param>
/// <returns>Response</returns>
public Niedax.D365.API.Models.D365_APIResponse writeRecord(Niedax.AX.TableRecordModels.TableRecord _record)
{
    this.writeNDXSNAllianceClients(_record);
    return response;
}
